/** Pings follow responsibility (no version bump: additive only). `lead_credential` is a lead token: an agent acting
 * for `owner`, only its hash kept. `task_act` is who filed, approved, cancelled, completed or handed on a task
 * (`lead` 1: the owner's lead; `person`/`why`: who the lead asked, and why). `notification_actor` is whose act made
 * a fact. `task_replacement` is the task that replaced a cancelled one. `project_mute` is a person's muted projects. */
const LEAD_QUIET_SCHEMA = `
CREATE TABLE IF NOT EXISTS lead_credential (
  id          TEXT PRIMARY KEY,
  owner       TEXT NOT NULL,
  secret_hash TEXT NOT NULL,
  created_at  TEXT NOT NULL,
  created_by  TEXT NOT NULL,
  revoked_at  TEXT,
  revoked_by  TEXT
);
CREATE INDEX IF NOT EXISTS lead_credential_owner ON lead_credential (owner);
CREATE TABLE IF NOT EXISTS task_act (
  id       INTEGER PRIMARY KEY AUTOINCREMENT,
  task_ref INTEGER NOT NULL,
  act      TEXT NOT NULL CHECK (act IN ('filed', 'approved', 'cancelled', 'completed', 'asked')),
  account  TEXT NOT NULL,
  lead     INTEGER NOT NULL DEFAULT 0 CHECK (lead IN (0, 1)),
  person   TEXT,
  why      TEXT,
  at       TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS task_act_task ON task_act (task_ref, id);
CREATE TABLE IF NOT EXISTS notification_actor (
  notification INTEGER PRIMARY KEY REFERENCES notification(id) ON DELETE CASCADE,
  account      TEXT NOT NULL,
  lead         INTEGER NOT NULL DEFAULT 0 CHECK (lead IN (0, 1))
);
CREATE TABLE IF NOT EXISTS task_replacement (
  task_ref  INTEGER PRIMARY KEY,
  successor TEXT NOT NULL,
  by        TEXT,
  at        TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS project_mute (
  account TEXT NOT NULL,
  repo    TEXT NOT NULL,
  at      TEXT NOT NULL,
  PRIMARY KEY (account, repo)
);
`;
/** A lead reply stopped at its deadline, in the thread as plain words: what happened, what it means, one next step. The
 * proposals it made before then are kept; the cost line only when an unknown cost paused chat. */
export function leadTimeoutNotice(keptProposals: boolean, unknownCost = false): string {
  return [
    unknownCost ? "The reply took too long and was stopped, and its cost isn't known yet, so chat is paused." : "The reply took too long and was stopped.",
    keptProposals ? "What it proposed is below." : null,
    unknownCost ? "Confirm the cost on the Chat page to turn chat back on." : "Send your message again, or ask for less at once.",
  ].filter(part => part !== null).join(" ");
}

/** Whether a turn's proposals stand: it answered, or it stopped at its deadline after its completed tool calls proposed them. */
export function leadTurnKeepsProposals(turn: { state: string; failureReason: string | null } | null): boolean {
  return turn !== null && (turn.state === "answered" || turn.state === "failed" && (turn.failureReason === "timeout" || turn.failureReason === "crashed"));
}

/** What the lead promised to follow up on (lead-commitments.ts; no version bump: additive only, so a build that
 * predates it still opens the store). `condition_json` is a task, attempt, check or time; `check_at` is when to look
 * next; `channel` is where it reports (`chat`: the conversation it was promised in); a promise lapses at `expires_at`. */
export const LEAD_COMMITMENT_SCHEMA = `
CREATE TABLE IF NOT EXISTS lead_commitment (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  owner          TEXT NOT NULL,
  repo           TEXT,
  thread         INTEGER NOT NULL,
  turn           INTEGER,
  channel        TEXT NOT NULL DEFAULT 'chat',
  what           TEXT NOT NULL,
  condition_json TEXT NOT NULL,
  check_at       TEXT NOT NULL,
  expires_at     TEXT NOT NULL,
  state          TEXT NOT NULL DEFAULT 'open' CHECK (state IN ('open', 'done', 'cancelled', 'expired')),
  created_at     TEXT NOT NULL,
  checked_at     TEXT,
  closed_at      TEXT,
  closed_by      TEXT,
  outcome        TEXT
);
CREATE INDEX IF NOT EXISTS lead_commitment_due ON lead_commitment (state, check_at);
CREATE INDEX IF NOT EXISTS lead_commitment_owner ON lead_commitment (owner, state, id);
`;
/** What still pings on the lead's own work: a security alert. */
const SECURITY_KINDS = new Set(["secret-detected", "security-release"]);
/** A failure that leaves nothing for the lead to try: the attempts are spent. */
const SPENT_KINDS = new Set(["attempts-exhausted", "plan-attempts-exhausted"]);
/** What stops a finished run reading stopped (Store.stopQuiescenceFact). */
export type StopFactKind = "open" | "alive" | "elsewhere" | "unprovable" | "unknown" | "settling";
export type TaskAct = "filed" | "approved" | "cancelled" | "completed" | "asked";
/** Store.stopQuiescenceFact, read safely: a deploy proves completion with this code over the INSTALLED runtime's store,
 * which may predate the method. There the older stopQuiescenceProblem decides, and its words give the kind. */
export function stopFactOf(store: Pick<Store, "stopQuiescenceProblem"> & Partial<Pick<Store, "stopQuiescenceFact">>, runId: number): { run: number; kind: StopFactKind; problem: string } | null {
  if (typeof store.stopQuiescenceFact === "function") return store.stopQuiescenceFact(runId);
  const problem = store.stopQuiescenceProblem(runId);
  if (problem === null) return null;
  const kind: StopFactKind = /still open|does not exist/.test(problem) ? "open"
    : /another host/.test(problem) ? "elsewhere"
    : /may still be running|still has|held by|has not finished|still has members/.test(problem) ? "alive"
    : /cannot be proven|could not be established|incomplete native/.test(problem) ? "unknown" : "unprovable";
  return { run: Number(/run #(\d+)/.exec(problem)?.[1] ?? runId), kind, problem };
}
export type TaskActRow = { act: TaskAct; account: string; lead: boolean; person: string | null; why: string | null; at: string };

/** The lead's one question to its owner (no version bump): at most one per answered turn, two to four short options;
 * "Something else" is implied. The tapped option comes back as the owner's next message, so nothing here is an answer:
 * a question is open while no later message from the owner sits in its thread. */
export const LEAD_ASK_SCHEMA = `
CREATE TABLE IF NOT EXISTS lead_ask (
  turn         INTEGER PRIMARY KEY REFERENCES mate_turn(id) ON DELETE CASCADE,
  thread       INTEGER NOT NULL REFERENCES lead_thread(id) ON DELETE CASCADE,
  question     TEXT NOT NULL,
  options_json TEXT NOT NULL,
  created_at   TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS lead_ask_thread ON lead_ask (thread, turn);
`;
/** Decisions in the chat app (chat-decide.ts; no version bump: additive only). A token names one act on one card (the chat and message it rides); `digest` is
 * what the card showed — a receipt, a revision source, a task stamp, a plan or a commit. */
/** A flow's "Send to me" and "Person chooses" zones (no version bump: additive only). flow_send keeps what one visit sent its
 * person (shown on the card, and read again by every chat app that delivers it); telegram_flow_choice is one opaque button
 * per option for one visit of one card, placed on the message it rides. A reply to that message is the note
 * (telegram_flow_prompt, mode send-back). The chat apps keep their buttons beside their messages (chat-delivery-state.ts). */
export const FLOW_SEND_SCHEMA = `
CREATE TABLE IF NOT EXISTS flow_send (
  card         INTEGER NOT NULL REFERENCES flow_card(id),
  entry        INTEGER NOT NULL,
  stage        TEXT NOT NULL,
  person       TEXT NOT NULL,
  content_json TEXT NOT NULL,
  created_at   TEXT NOT NULL,
  PRIMARY KEY (card, entry)
);
`;

/** An owner's lasting choice to approve plans and merges from their paired chat (chat-approval.ts), for all their
 * projects (scope '*') or one (its path), with the limits they agreed to. Off unless a row says on; a project's own row
 * outranks the all-projects one. `generation` is the account's at the change: a reset password ends it. */
/** What a running agent did last (live tasks): one row per run, a fixed kind from live.ts's
 * vocabulary and when — never text, tool names or arguments. Display state, not evidence;
 * a finished run's row goes with the live log's own retention (sweepRunActivity). */
export const RUN_ACTIVITY_SCHEMA = `
CREATE TABLE IF NOT EXISTS run_activity (
  run  INTEGER PRIMARY KEY REFERENCES run(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('session','message','edit','command','read','search','lookup','plan','delegate','tool')),
  at   TEXT NOT NULL
);
`;

export const CHAT_APPROVAL_SCHEMA = `
CREATE TABLE IF NOT EXISTS chat_approval_setting (
  approver             TEXT NOT NULL,
  scope                TEXT NOT NULL,
  enabled              INTEGER NOT NULL CHECK (enabled IN (0,1)),
  full_access          INTEGER NOT NULL DEFAULT 0 CHECK (full_access IN (0,1)),
  attempt_cap_microusd INTEGER CHECK (attempt_cap_microusd IS NULL OR attempt_cap_microusd >= 0),
  generation           INTEGER NOT NULL,
  digest               TEXT NOT NULL,
  updated_by           TEXT NOT NULL,
  updated_at           TEXT NOT NULL,
  PRIMARY KEY (approver, scope)
);
`;


export const CHAT_DECIDE_SCHEMA = `
CREATE TABLE IF NOT EXISTS chat_decide_action (
  token       TEXT PRIMARY KEY,
  channel     TEXT NOT NULL,
  binding     INTEGER NOT NULL,
  chat        TEXT NOT NULL,
  message     TEXT,
  act         TEXT NOT NULL CHECK (act IN ('accept','changes','retry','approve','not-now','merge')),
  phase       TEXT NOT NULL CHECK (phase IN ('offer','yes','cancel')),
  task_id     TEXT NOT NULL,
  run         INTEGER,
  digest      TEXT NOT NULL,
  created_at  TEXT NOT NULL,
  expires_at  TEXT NOT NULL,
  consumed_at TEXT
);
CREATE INDEX IF NOT EXISTS chat_decide_action_message ON chat_decide_action (channel, chat, message);
CREATE TABLE IF NOT EXISTS chat_decide_prompt (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  channel     TEXT NOT NULL,
  binding     INTEGER NOT NULL,
  chat        TEXT NOT NULL,
  task_id     TEXT NOT NULL,
  run         INTEGER NOT NULL,
  digest      TEXT NOT NULL,
  message     TEXT,
  created_at  TEXT NOT NULL,
  expires_at  TEXT NOT NULL,
  consumed_at TEXT
);
CREATE INDEX IF NOT EXISTS chat_decide_prompt_open ON chat_decide_prompt (channel, binding, consumed_at);
`;

export type LeadAsk = { turn: number; thread: number; question: string; options: string[]; createdAt: string };
export const LEAD_ASK_OTHER = "Something else";
/** How long the question's buttons work, on every channel. */
export const LEAD_ASK_TTL_MS = 7 * 86_400_000;
/** What a turn the lead starts itself for automatic crew updates says in the owner's place (lead-follow.ts): never their answer. */
export const LEAD_FOLLOW_MESSAGE = "Automatic crew update: inspect the saved results or decisions and tell me what needs attention. Do not rerun work.";

/** Settings → Integrations (no version bump): each integration's last check. `outcome` is ok, failed, or absent (the check found
 * nothing set up, such as no `gh` sign-in). `ok_at` and `error`/`error_at` keep the last success and the last
 * failure across checks, so a row can say both. `account` is a display name only, never a credential. */
export const INTEGRATIONS_SCHEMA = `
CREATE TABLE IF NOT EXISTS integration_check (
  key         TEXT PRIMARY KEY,
  outcome     TEXT NOT NULL CHECK (outcome IN ('ok', 'failed', 'absent')),
  account     TEXT,
  detail      TEXT,
  problem     TEXT,
  checked_at  TEXT NOT NULL,
  ok_at       TEXT,
  error       TEXT,
  error_at    TEXT
);
`;
/** Sprint 8: database backups. One settings row (off, or every so many hours, keeping the newest N in a folder; no
 * folder means `backups` beside the database), every backup's outcome, and a lease the console's backup loop holds
 * and renews while it runs: one process backs up at a time, and a restore sees that the console is running. */
const BACKUP_SCHEMA = `
CREATE TABLE IF NOT EXISTS backup_settings (
  id          INTEGER PRIMARY KEY CHECK (id = 1),
  enabled     INTEGER NOT NULL DEFAULT 1,
  every_hours INTEGER NOT NULL DEFAULT 24,
  keep        INTEGER NOT NULL DEFAULT 7,
  folder      TEXT
);
CREATE TABLE IF NOT EXISTS backup_run (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  trigger        TEXT NOT NULL CHECK (trigger IN ('scheduled', 'manual')),
  started_at     TEXT NOT NULL,
  finished_at    TEXT,
  ok             INTEGER,
  file           TEXT,
  bytes          INTEGER,
  schema_version INTEGER,
  removed        INTEGER NOT NULL DEFAULT 0,
  error          TEXT
);
CREATE TABLE IF NOT EXISTS backup_lease (
  id         INTEGER PRIMARY KEY CHECK (id = 1),
  holder     TEXT,
  held_until TEXT
);
`;
export type BackupSettings = { enabled: boolean; everyHours: number; keep: number; folder: string | null };
export const DEFAULT_BACKUP_SETTINGS: BackupSettings = { enabled: true, everyHours: 24, keep: 7, folder: null };
export type BackupRun = { id: number; trigger: "scheduled" | "manual"; startedAt: string; finishedAt: string | null; ok: boolean | null; file: string | null; bytes: number | null; schemaVersion: number | null; removed: number; error: string | null };
/** The settings in words, for the ledger. */
export function backupSettingsWords(settings: BackupSettings): string {
  if (!settings.enabled) return `off, keep ${settings.keep}, ${settings.folder ?? "the default folder"}`;
  return `every ${settings.everyHours === 1 ? "hour" : `${settings.everyHours} hours`}, keep ${settings.keep}, ${settings.folder ?? "the default folder"}`;
}
/** One row per run for its approved project check: the live progress while
 * it runs and the machine-owned result once it finishes, so the task page,
 * lifecycle updates, `status` and `task wait` all read the same record
 * without opening retained logs. The sealed receipt stays the evidence.
 * `status` is empty until the result is recorded; `snapshot` is empty until
 * the check's output shows progress. `release` is copied from the run's
 * Strict mode when the result is recorded, so the newest release check is
 * one indexed read. A run without a result is history from before results
 * were recorded, or a check still running. The run table itself is
 * unchanged. (This table absorbed the separate v106 check_progress table.) */
const RUN_CHECK_TABLE = (name: string) => `
CREATE TABLE IF NOT EXISTS ${name} (
  run         INTEGER PRIMARY KEY REFERENCES run(id) ON DELETE CASCADE,
  status      TEXT CHECK (status IS NULL OR status IN ('passed', 'failed', 'not-run')),
  exit_code   INTEGER,
  suites_json TEXT NOT NULL DEFAULT '[]',
  release     INTEGER NOT NULL DEFAULT 0 CHECK (release IN (0, 1)),
  recorded_at TEXT,
  snapshot    TEXT,
  line        TEXT,
  final       INTEGER NOT NULL DEFAULT 0 CHECK (final IN (0, 1)),
  updated_at  TEXT,
  notified_at TEXT
);`;
const RUN_CHECK_SCHEMA = `${RUN_CHECK_TABLE("run_check")}
CREATE INDEX IF NOT EXISTS run_check_release ON run_check (run DESC) WHERE release = 1;
`;

/** A file from before the merge keeps a result-only run_check (status
 * required) and a separate check_progress. Move both into the one record,
 * in one transaction. Rows for a run that no longer exists are left behind.
 * The old check_progress stays as it was: a deploy refuses a migration that
 * loses a table's historical rows. Runs once: a merged file is untouched, so
 * the old progress never overwrites newer. */
function mergeCheckTables(db: Database): void {
  if (hasColumn(db, "run_check", "snapshot")) return;
  const progress = tableExists(db, "check_progress");
  db.exec("BEGIN IMMEDIATE");
  try {
    db.exec(RUN_CHECK_TABLE("run_check_next"));
    db.exec(`INSERT INTO run_check_next (run, status, exit_code, suites_json, release, recorded_at)
      SELECT run, status, exit_code, suites_json, release, recorded_at FROM run_check WHERE run IN (SELECT id FROM run)`);
    db.exec("DROP TABLE run_check");
    db.exec("ALTER TABLE run_check_next RENAME TO run_check");
    db.exec("CREATE INDEX IF NOT EXISTS run_check_release ON run_check (run DESC) WHERE release = 1");
    if (progress) {
      db.exec(`INSERT INTO run_check (run, snapshot, line, final, updated_at, notified_at)
        SELECT run, snapshot, line, final, updated_at, notified_at FROM check_progress WHERE run IN (SELECT id FROM run)
        ON CONFLICT(run) DO UPDATE SET snapshot = excluded.snapshot, line = excluded.line,
          final = excluded.final, updated_at = excluded.updated_at, notified_at = excluded.notified_at`);
    }
    db.exec("COMMIT");
  } catch (error) {
    db.exec("ROLLBACK");
    throw error;
  }
}

export type RunCheckSuite = {
  name: string;
  status: "passed" | "failed" | "not-run";
  exitCode: number | null;
};
export type RunCheck = { status: "passed" | "failed" | "not-run"; exitCode: number | null; suites: RunCheckSuite[] };

const isCheckExitCode = (value: unknown): boolean =>
  value === null || (Number.isSafeInteger(value) && Number(value) >= 0 && Number(value) <= 2_147_483_647);

/** Read a stored suite list; a malformed optional summary reads as no suite detail. */
export function checkSuitesOf(value: unknown): RunCheckSuite[] {
  try {
    const read = readStoreColumn("run_check.suites_json", value ?? "[]");
    if (!read.ok) return [];
    return read.value.filter((one): one is RunCheckSuite => {
      if (one === null || typeof one !== "object") return false;
      const row = one as Record<string, unknown>;
      return typeof row["name"] === "string" && row["name"].trim() !== "" && row["name"].length <= 80 &&
        ["passed", "failed", "not-run"].includes(String(row["status"])) && isCheckExitCode(row["exitCode"]);
    }).slice(0, 8);
  } catch {
    return [];
  }
}

export type MonitoringStatus = { sink: string; target: string | null; through: number; sent: number; lastOkAt: string | null; lastError: string | null; lastErrorAt: string | null; failures: number; nextTryAt: string | null };

export type CheckProgress = CheckProgressSnapshot & { run: number; updatedAt: string; notifiedAt: string | null };

/** The detail on a task's registration written again at its filing (v103), over a ref an earlier lookup made. */
const REGISTERED_AT_FILING = "again, as it was filed";
/** A ledger entry with its seal (v103); null until the next pass seals it. */
export type SealedLedgerEntry = LedgerEntry & { seal: { prev: string; hash: string } | null };
// v103 chains the action ledger (every entry sealed with the one before it), keeps checkpoints of the chain, and records subagent tool calls (from the store) and minted coordinators (by trigger) in it.
// v104 keeps where each monitoring destination (the audit stream to a webhook or a folder, traces to an OpenTelemetry collector) has delivered to, and who is sending.
// v105 prices every run (reported, or tokens at the catalogue price) and keeps monthly budgets per project, person, subagent and installation.
// v106 keeps the organisation policy, retention periods, backup settings and runs, check progress, and runner capacity changes.
// v107 keeps a check's progress and result in one record (run_check absorbs check_progress).
// v108 keeps sign-in pauses: one incident per provider whose sign-in stopped working (provider_auth_pause).
// v109 remembers which sign-in pause parked a task (task_ref.auth_wait_pause), so reviews and other runs outside the tick wait for it too.
// v110 lets the action ledger record commands a person ran on this server with their API token (source 'api', or 'mcp' from their agent).
// v111 keeps an API token's project limit and its rotation: the token that replaced it, and when the old one stops.
// v112 keeps request budgets for API tokens: owner overrides (request_budget_limit) and saved usage (request_budget_usage).
// v113 keeps MCP sign-ins (OAuth): registered clients, one-time codes, and each grant's binding to its API token.
// v114 names one exact shape, migrated once: a settled run keeps one process summary instead of its exited witnesses,
// notification's single-destination delivery columns move into legacy receipts, and the workspace revision triggers are gone
// (the write wrapper bumps the revision). Every later DDL change bumps the version.
// v115 removes contests, held sessions, fallback chains and routines (each routine becomes a scheduled flow).
// v116 keeps every chat app (Telegram, Slack, Discord, Teams) in one set of chat tables keyed by provider, moving each old table's rows.
// v117 (D5) names one AI concept, the lead: the mate's tables become the lead's (mate_* → lead_*), and teammates become
// the lead's subagents (teammate* → subagent*, their rows' teammate column → subagent), with every row, id and link kept.
// mate_turn (and chat_turn.mate_turn) keep their names this release: the update gate the previous build's updater lifts
// names them byte for byte (desktop-update-gate.ts), so they move once every updater reads either name.
export const SCHEMA_VERSION = 117;

/** v117: each table renamed, by its old name. Rows, ids, foreign keys and indexes go with it (renameForV117). */
export const V117_RENAMED_TABLES: Readonly<Record<string, string>> = Object.freeze({
  mate_session: "lead_session", mate_thread: "lead_thread", mate_message: "lead_message", mate_proposal: "lead_proposal",
  mate_ask: "lead_ask", mate_turn_evidence: "lead_turn_evidence",
  teammate: "subagent", teammate_version: "subagent_version", teammate_event: "subagent_event", teammate_question: "subagent_question",
  teammate_tool: "subagent_tool", teammate_call: "subagent_call", teammate_turn: "subagent_turn", teammate_memory: "subagent_memory",
  teammate_suggestion: "subagent_suggestion",
});
/** v117: the columns renamed with them (by the table's new name): a subagent's rows name it `subagent`. */
export const V117_RENAMED_COLUMNS: readonly (readonly [table: string, from: string, to: string])[] = Object.freeze(
  ["subagent_version", "subagent_event", "subagent_question", "subagent_tool", "subagent_call", "subagent_turn", "subagent_memory", "subagent_suggestion"]
    .map(table => [table, "teammate", "subagent"] as const));
/** v117: the internal kinds that said 'teammate' and now say 'subagent' (a step run's kind, a budget's scope, a memory's source,
 * a task's filer); the first three are held by a CHECK that names it. */
const V117_KINDS: readonly (readonly [table: string, column: string])[] = [["flow_step_run", "kind"], ["budget", "scope_kind"], ["subagent_memory", "source"], ["task_ref", "filed_by_kind"]];
const V117_OLD_NAME: Readonly<Record<string, string>> = Object.fromEntries(Object.entries(V117_RENAMED_TABLES).map(([old, now]) => [now, old]));
/** The table's name in this file: before v117 runs (the preflight), a renamed table still has its old one. */
function presentTable(db: Database, name: string): string {
  const old = V117_OLD_NAME[name];
  return old !== undefined && !tableExists(db, name) && tableExists(db, old) ? old : name;
}
/** A row `PRAGMA foreign_key_check` reports, by today's table names: a row already pointing nowhere before v117 is the
 * same row after it, though RENAME now reports it (and what it points at) under the new names. */
export function orphanKey(row: Record<string, unknown>): string {
  const named = (value: unknown) => typeof value === "string" ? V117_RENAMED_TABLES[value] ?? value : value;
  return JSON.stringify({ table: named(row["table"]), rowid: row["rowid"], parent: named(row["parent"]), fkid: row["fkid"] });
}
/** Shapes compare by today's names: a pre-v117 table, index or reference names the same shape by its old one. */
const V117_LEGACY_NAMES = /\b(?:mate_(?:session|thread|message|proposal|turn_evidence|ask)|teammate(?:_(?:version|event|question|tool|call|turn|memory|suggestion))?)\b/g;

/** v115: the tables migrateToV115 drops. */
export const V115_DROPPED_TABLES: readonly string[] = Object.freeze([
  "tournament_terms", "contest", "contestant",
  "routine", "routine_fire",
  "attended_authorization", "session_turn", "held_session",
  "fallback_config", "fallback_cycle", "fallback_transition",
]);
/** The foreign keys other tables kept to removed rows, exactly as their DDL wrote them. */
const V115_DROPPED_REFERENCES = /\s+REFERENCES (?:contestant|contest|tournament_terms|session_turn|attended_authorization|held_session|fallback_cycle|fallback_config|fallback_transition|routine|routine_fire)\(id\)(?: ON DELETE CASCADE)?/g;

/**
 * The migrations `toolroll update` may carry a database through in place: each
 * one only adds (a table, a column, an accepted value) and leaves every saved row
 * as it was, so the updater's rehearsal on a copy (same history, integrity ok)
 * proves it and the verified backup undoes it. Any migration not listed here
 * needs the separate verified migration procedure. The desktop update never
 * migrates and does not read this list.
 *
 * v108 only adds provider_auth_pause; v109 only adds task_ref.auth_wait_pause,
 * so a database at the v107 baseline (0.5.0) takes the same update.
 * v110 rebuilds action_ledger only to widen its source check ('api', 'mcp'):
 * every row, id and hash-chain link is copied unchanged. v111 adds nullable
 * api_token columns (project limit, rotation); existing tokens read as before.
 * v112 only adds the two request-budget tables.
 * v113 adds MCP sign-in tables and API-token purpose metadata.
 * v114 is the one declared exception to "only adds", and the rehearsal checks
 * it as such: a settled run's exited process witnesses become one summary row
 * (rows removed equal the witnesses summarized), and notification drops its
 * delivery columns only after every value moves into one legacy receipt per row
 * (rows and ids carried whole; legacy receipts added equal the rows carried).
 * v115 removes contests, held sessions, fallback chains and routines, and is
 * checked under rules named for exactly that: the eleven removed tables may go
 * whole, every kept flow and trigger row stays as it was, and the only rows
 * added are one flow and one schedule trigger per saved routine (paused unless
 * the routine was approved and running). Its other changes add a column or
 * settle rows in place; a database whose removed features still held a hold
 * to lift or place changes that table's rows and is refused, so it takes the
 * separate procedure. v116 is the next declared exception: every row of the 70 old
 * per-app chat tables moves into the shared chat tables keyed by provider, in one
 * transaction that checks each count before the old tables are dropped; the
 * rehearsal checks each moved table's rows arrived (HISTORY_RULES). v117 renames the mate's tables to the lead's and the
 * teammates' to its subagents' (SQLite's RENAME, every row, id and link carried), renames their teammate column, and rewrites four internal kinds from 'teammate' to 'subagent' in place; the rehearsal checks
 * each renamed table's rows arrived under its new name.
 */
export const UPDATE_SAFE_MIGRATIONS: readonly number[] = Object.freeze([108, 109, 110, 111, 112, 113, 114, 115, 116, 117]);

/** Whether a database settled at `version` reaches this build's schema through update-safe migrations alone. */
export function updateSafeSchema(version: number | null): boolean {
  if (version === null || !Number.isSafeInteger(version) || version <= 0 || version > SCHEMA_VERSION) return false;
  for (let next = version + 1; next <= SCHEMA_VERSION; next++) if (!UPDATE_SAFE_MIGRATIONS.includes(next)) return false;
  return true;
}

/** v102: a project's approval rules, and each person's approval of an exact scope (two are needed for protected work). */
const APPROVAL_SCHEMA = `
CREATE TABLE IF NOT EXISTS approval_policy (
  repo            TEXT PRIMARY KEY,
  not_requester   INTEGER NOT NULL DEFAULT 0 CHECK (not_requester IN (0,1)),
  protect_project INTEGER NOT NULL DEFAULT 0 CHECK (protect_project IN (0,1)),
  protected_paths TEXT NOT NULL DEFAULT '[]',
  updated_by      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS scope_approval_vote (
  task_id  TEXT NOT NULL,
  digest   TEXT NOT NULL,
  approver TEXT NOT NULL,
  at       TEXT NOT NULL,
  PRIMARY KEY (task_id, digest, approver)
);
CREATE TABLE IF NOT EXISTS scope_author (
  task_id TEXT NOT NULL,
  digest  TEXT NOT NULL,
  author  TEXT NOT NULL,
  at      TEXT NOT NULL,
  PRIMARY KEY (task_id, digest, author)
);
`;

/** v101: API tokens and the browser sessions that survive a restart. Only hashes of their secrets are kept. */
const CREDENTIALS_SCHEMA = `
CREATE TABLE IF NOT EXISTS api_token (
  id           TEXT PRIMARY KEY,
  account      TEXT NOT NULL REFERENCES approver(name),
  name         TEXT NOT NULL,
  secret_hash  TEXT NOT NULL,
  access       TEXT NOT NULL CHECK (access IN ('read','act')),
  created_at   TEXT NOT NULL,
  created_by   TEXT NOT NULL,
  expires_at   TEXT NOT NULL,
  last_used_at TEXT,
  revoked_at   TEXT,
  revoked_by   TEXT
);
CREATE INDEX IF NOT EXISTS api_token_account ON api_token (account);
CREATE TABLE IF NOT EXISTS web_session (
  id_hash          TEXT PRIMARY KEY,
  account          TEXT NOT NULL,
  csrf             TEXT NOT NULL,
  role             TEXT NOT NULL CHECK (role IN ('approver','viewer')),
  generation       INTEGER NOT NULL,
  created_at       INTEGER NOT NULL,
  last_seen        INTEGER NOT NULL,
  project          TEXT,
  project_revision INTEGER NOT NULL,
  sso_at           INTEGER,
  agent            TEXT,
  address          TEXT
);
CREATE INDEX IF NOT EXISTS web_session_account ON web_session (account);
`;
/**
 * v113: MCP sign-in (OAuth 2.1, mcp-oauth.ts). A registered client, a one-time code (its hash, a minute at most), and
 * each grant: the ordinary API token it signs in with (revoked like any other), the account generation and exact
 * projects the person chose, and every issued refresh-secret hash (any replay ends the whole family).
 */
const OAUTH_SCHEMA = `
CREATE TABLE IF NOT EXISTS oauth_client (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  redirect_json TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  source_hash   TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS oauth_client_source ON oauth_client (source_hash);
CREATE TABLE IF NOT EXISTS oauth_code (
  hash         TEXT PRIMARY KEY,
  client       TEXT NOT NULL REFERENCES oauth_client(id),
  account      TEXT NOT NULL,
  generation   INTEGER NOT NULL,
  access       TEXT NOT NULL CHECK (access IN ('read','act')),
  projects_json TEXT NOT NULL,
  redirect_uri TEXT NOT NULL,
  resource     TEXT NOT NULL,
  challenge    TEXT NOT NULL,
  expires_at   TEXT NOT NULL,
  used_at      TEXT,
  token        TEXT
);
CREATE TABLE IF NOT EXISTS oauth_grant (
  token              TEXT PRIMARY KEY REFERENCES api_token(id),
  client             TEXT NOT NULL REFERENCES oauth_client(id),
  account            TEXT NOT NULL,
  generation         INTEGER NOT NULL,
  projects_json      TEXT NOT NULL,
  resource           TEXT NOT NULL,
  access_expires_at  TEXT NOT NULL,
  renew_hash       TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS oauth_grant_client ON oauth_grant (client);
CREATE TABLE IF NOT EXISTS oauth_refresh (
  token TEXT NOT NULL REFERENCES oauth_grant(token),
  hash  TEXT NOT NULL,
  PRIMARY KEY (token, hash)
);
`;
export type OAuthClientRow = { id: string; name: string; redirectUris: string[]; createdAt: string };
export type OAuthCodeRow = { client: string; account: string; generation: number; access: "read" | "act"; projects: string[]; redirectUri: string; resource: string; challenge: string; expiresAt: string; usedAt: string | null; token: string | null };
export type OAuthGrantRow = { token: string; client: string; account: string; generation: number; projects: string[]; resource: string; accessExpiresAt: string; refreshHash: string };
const stringList = (raw: unknown): string[] => { try { const value = JSON.parse(String(raw)) as unknown; return Array.isArray(value) && value.every((one): one is string => typeof one === "string") ? value : []; } catch { return []; } };
export type ApiTokenRow = { id: string; account: string; name: string; access: "read" | "act"; createdAt: string; createdBy: string; expiresAt: string; lastUsedAt: string | null; revokedAt: string | null; revokedBy: string | null;
  /** v113: MCP manages its own access-secret rotation. */
  purpose: TokenPurpose;
  /** v111: the projects it is limited to (null: every project its person may use). */
  projects: string[] | null;
  /** v111: the token it replaced, the one that replaced it, and when this one stops after being replaced. */
  replaces: string | null; replacedBy: string | null; overlapUntil: string | null };
export type WebSessionRow = { idHash: string; account: string; csrf: string; role: "approver" | "viewer"; generation: number; createdAt: number; lastSeen: number; project: string | null; projectRevision: number; ssoAt: number | null; agent: string | null; address: string | null };

/** v100: which account each identity-provider identity (issuer + subject) signs in as. */
const SSO_SCHEMA = `
CREATE TABLE IF NOT EXISTS sso_identity (
  issuer       TEXT NOT NULL,
  subject      TEXT NOT NULL,
  account      TEXT NOT NULL REFERENCES approver(name),
  email        TEXT,
  created_at   TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  PRIMARY KEY (issuer, subject)
);
CREATE INDEX IF NOT EXISTS sso_identity_account ON sso_identity (account);
`;

/**
 * Every timestamp column holds `Date.prototype.toISOString()` output and
 * nothing else, which is UTC, zero-padded, and always three fractional
 * digits. Expiry is then a string comparison, which is only sound because that
 * format sorts lexicographically the same way it sorts chronologically.
 *
 * The invariant is load-bearing, so it is stated here rather than assumed: a
 * timestamp written with an offset (`-07:00`) or with different fractional
 * precision would compare wrong, and a lease would expire early or never.
 * Anything writing to this database goes through a `Date`.
 */

/** The backend name the built-in store registers itself under. */
export const BUILT_IN = "built-in";

export type TaskState = "queued" | "running" | "done" | "failed" | "cancelled";

type CancellationRefusal = "reason-required" | "bad-reason";
type CancellationTransition = { changed: boolean; reason?: never } | { changed: false; reason: CancellationRefusal };

/** States from which no further work is dispatched. */
export const TERMINAL_STATES: readonly TaskState[] = ["done", "failed", "cancelled"];

export type Task = {
  id: string;
  title: string;
  state: TaskState;
  createdAt: string;
  updatedAt: string;
  /** Queue rank — 0 is filing order; higher is picked sooner. Scheduling
   * only, never authority: approval gates are untouched by it. */
  priority: number;
};

export type TaskRef = {
  id: number;
  backend: string;
  externalId: string;
  /** Where the work lives, when known. null dispatches anywhere; no gap claims it. */
  repo: string | null;
  /** The worker this task is reserved for; null = any free worker.
   * Scheduling only — enforced in the claim primitive, never authority. */
  assignedRunner: string | null;
  /** The coordinator that filed this task (v31) — authoritative linkage,
   * written only by the branded door; null is every other filer. */
  coordinatorCid: string | null;
  zones: string[];
  capabilityRequirements: string[];
  parkRate: number;
  /** Consecutive concluded failures. Three stalls the task; any success resets. */
  strikes: number;
  /** Planning mode: 'requested' dispatches a planner; 'drafted' awaits review. */
  plan: "requested" | "drafted" | null;
  /** Planning failures, counted apart from build strikes by design. */
  planStrikes: number;
  /** What comes back (v34): a branch to publish, or a report to read.
   * Set at filing and never rewritten — a scout's strikes are the task's. */
  deliverable: "branch" | "report";
  /** The pinned agent, when an approved standing order stamped one. Authoritative. */
  agentProvider: string | null;
  agentModel: string | null;
  /** Durable per-task override. null means the installation default is used
   * the next time this task's scope is filed. Approved scopes still bind the
   * concrete provider argv and never change under a setting edit. */
  permissionMode?: UnattendedPermissionMode | null;
  /** Durable per-task evidence-policy override. null inherits the
   * installation default when a scope is next written. */
  qualityMode?: QualityMode | null;
  /** v47: the approver's per-phase route overrides, applied when the next
   * scope is filed and recorded in the sealed route. null = the stored
   * list is malformed; the next filing goes unresolved rather than routing
   * as if nobody had overridden anything. */
  routeOverrides?: RouteOverride[] | null;
  /** v2 routing: how big the change is (sized at filing by the classifier
   * or the description, or set by a person); null when never sized. */
  sizing?: TaskSizing | null;
  /** The build tier the task's latest filed route chose (light, routine,
   * strong — or override/pinned when a person or a pin chose the agent). */
  routeTier?: string | null;
  /** Plan pins (P2/C7): read ONLY by the plan phase; precedence plan pin
   * > plan flags > plan config > installation > default. */
  planProvider: string | null;
  planModel: string | null;
  /** The task whose reviewed run this one revises (M6.8); null ordinarily. */
  revisionOf: string | null;
  /** The immutable brief artifact carrying the exact comment batch. */
  revisionBriefArtifact: number | null;
  /** Recorded, not asserted: what the grant's selector is checked against. */
  origin: TaskOrigin;
};

/** A standing order: a pre-approved template whose instances build unattended. */

export type ExecutionSlot = {
  id: number;
  runner: string;
  state: "reserved" | "running" | "released";
  run: number | null;
  incarnation: string | null;
  processGroup: number | null;
  reservedAt: string;
  runningAt: string | null;
  releasedAt: string | null;
};

